'use strict';
const Packet = require('./packet');
const readers = [];
readers[1] = Packet.prototype.readInt8;
readers[2] = Packet.prototype.readInt16;
readers[6] = Packet.prototype.missing;
function run() {
  const p = new Packet([5, 1, 2, 3, 4]);
  const out = [];
  out.push(readers[1].call(p));
  out.push(readers[2].call(p));
  out.push(typeof readers[6]);
  out.push(readers.length);
  return out.join(',');
}
module.exports = { run };
